local function bx(a,b)
 a,b=a%256,b%256
 local r,p=0,1
 for _=1,8 do local aa,bb=a%2,b%2 if aa~=bb then r=r+p end a,b,p=(a-aa)/2,(b-bb)/2,p*2 end
 return r
end
