local PAD=0
local PASSES={{66,43,23},{17,37,19},{238,31,41},{92,47,29},{165,33,17}}

-- assemble
local str=concat(C)
local out={}
local n=#str
local i=1
while i+4<=n do
 local v=0
 for j=0,4 do v=v*85+(AM[sub(str,i+j,i+j)] or 0) end
 ins(out,char(floor(v/16777216)%256,floor(v/65536)%256,floor(v/256)%256,v%256))
 i=i+5
end
local payload=concat(out)
if PAD>0 then payload=sub(payload,1,#payload-PAD) end

-- xor decrypt (byte-safe)
local function dxor(data,seed,mul,add)
 local nn=#data local o={} local state=seed%256
 for ii=1,nn do
  state=(state*mul+add+(ii-1)%256)%256
  o[ii]=char(bx(byte(data,ii),bx(state,((ii-1)*7+13)%256)))
 end
 return concat(o)
end
for pi=1,#PASSES do
 local p=PASSES[pi]
 payload=dxor(payload,p[1],p[2],p[3])
end

-- unpack RLE
local data=payload
local o={} i=1 n=#data
while i<=n do
 local b=byte(data,i)
 if b==255 then
  local t=byte(data,i+1)
  if t==0 then
   local d=byte(data,i+2) local l=byte(data,i+3)
   local start=#o-d+1
   for j=0,l-1 do o[#o+1]=o[start+j] end
   i=i+4
  elseif t==1 then
   local l=byte(data,i+2) local v=byte(data,i+3)
   for j=1,l do o[#o+1]=v end
   i=i+4
  else
   o[#o+1]=255 i=i+2
  end
 else
  o[#o+1]=b i=i+1
 end
end
local chars={}
for k=1,#o do chars[k]=char(o[k]) end
local decoded=concat(chars)

local fn,err=loadf(decoded)
if not fn then
 if E.warn then E.warn('[NovaOBF] load failed: '..tostring(err)) end
 return
end
return fn(...)
end)(...)
